import numpy as np


def min_max_dist_dim3_14() -> np.ndarray:
    """Optimize spherical-code seeds, then polish them as free 3D packings."""
    from scipy.optimize import minimize

    n = 14
    ii, jj = np.triu_indices(n, 1)

    def d2(p):
        q = p[ii] - p[jj]
        return np.einsum("ij,ij->i", q, q)

    c = np.sqrt(3.0) / 2.0
    h = np.sqrt((2.0 * c - 1.0) / (3.0 + 2.0 * c))
    a = np.arange(6.0) * np.pi / 3.0
    th0 = np.r_[np.full(6, np.arccos(h)), np.full(6, np.arccos(-h))]
    ph0 = np.r_[a, a + np.pi / 6.0]

    def sphere(x):
        th, ph = x[:12], x[12:24]
        ring = np.column_stack((
            np.sin(th) * np.cos(ph),
            np.sin(th) * np.sin(ph),
            np.cos(th),
        ))
        return np.vstack(([[0., 0., 1.], [0., 0., -1.]], ring))

    def sstart(th, ph):
        p = sphere(np.r_[th, ph])
        return np.r_[th, ph, .995 * d2(p).min()]

    def scons(x):
        return d2(sphere(x)) - x[24]

    rng = np.random.default_rng(714029)
    starts = [sstart(th0, ph0)]
    for scale in (.18, .35, .60):
        for _ in range(6):
            th = np.clip(th0 + rng.normal(0, scale, 12), 1e-5, np.pi - 1e-5)
            starts.append(sstart(th, ph0 + rng.normal(0, scale, 12)))
    for _ in range(4):
        starts.append(sstart(
            np.arccos(rng.uniform(-.96, .96, 12)),
            rng.uniform(-np.pi, np.pi, 12),
        ))

    sbounds = ([(1e-5, np.pi - 1e-5)] * 12 +
               [(-10., 10.)] * 12 + [(0., 4.)])
    spherical = []
    for x0 in starts:
        result = minimize(
            lambda x: -x[24], x0, method="SLSQP", bounds=sbounds,
            constraints={"type": "ineq", "fun": scons},
            options={"maxiter": 1800, "ftol": 1e-11, "disp": False},
        )
        spherical.append(sphere(result.x))

    def unpack(x):
        return np.vstack((np.zeros(3), x[:39].reshape(13, 3)))

    def pack(p, noise=None):
        p = p.copy()
        p -= p[0]
        if noise is not None:
            p[1:] += noise
        p /= np.sqrt(d2(p).max())
        return np.r_[p[1:].ravel(), d2(p).min()]

    def cons(x):
        ds = d2(unpack(x))
        return np.r_[ds - x[39], 1. - ds]

    def jac(x):
        p = unpack(x)
        out = np.zeros((182, 40))
        for k, (i, j) in enumerate(zip(ii, jj)):
            v = 2. * (p[i] - p[j])
            if i:
                s = slice(3 * (i - 1), 3 * i)
                out[k, s] = v
                out[91 + k, s] = -v
            if j:
                s = slice(3 * (j - 1), 3 * j)
                out[k, s] = -v
                out[91 + k, s] = v
            out[k, 39] = -1.
        return out

    bounds = [(-1.05, 1.05)] * 39 + [(0., 1.)]

    def refine(x0):
        return minimize(
            lambda x: -x[39], x0,
            jac=lambda x: np.r_[np.zeros(39), -1.],
            method="SLSQP", bounds=bounds,
            constraints={"type": "ineq", "fun": cons, "jac": jac},
            options={"maxiter": 2500, "ftol": 2e-12, "disp": False},
        )

    spherical.sort(key=lambda p: d2(p).min(), reverse=True)
    best = spherical[0]
    value = d2(best).min() / d2(best).max()

    shake = np.random.default_rng(290317)
    free_starts = [pack(p) for p in spherical[:12]]
    for p in spherical[:6]:
        for scale in (.012, .035, .08, .15):
            free_starts.append(pack(p, shake.normal(0, scale, (13, 3))))

    for x0 in free_starts:
        candidate = unpack(refine(x0).x)
        score = d2(candidate).min() / d2(candidate).max()
        if score > value:
            best, value = candidate, score

    for scale in (.008, .02, .05, .10):
        for _ in range(3):
            candidate = unpack(refine(
                pack(best, shake.normal(0, scale, (13, 3)))
            ).x)
            score = d2(candidate).min() / d2(candidate).max()
            if score > value:
                best, value = candidate, score

    return best


